window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c1c8ab414c6ba407"]={"versions": [{"id": "FIG-c1c8ab414c6ba407", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen externem Diagnose-Tester (Generic Scan Tool), dem Diagnostic Communication Manager (Dcm) und dem Diagnostic Event Manager (Dem) im Rahmen des UDS-Dienstes zum Löschen von Fehlergedächtniseinträgen (Clear Diagnostic Information, Service 0x14 bzw. 0x04) innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Generic Scan Tool</code>: Externes Diagnoseprüfgerät bzw. Tester.</li>\n<li><code>Dcm</code> («module»): Diagnostic Communication Manager der AUTOSAR-Basissoftware zur Protokollabwicklung der Diagnoseschicht.</li>\n<li><code>Dem</code> («module»): Diagnostic Event Manager der AUTOSAR-Basissoftware zur Verwaltung von Fehlerspeichereinträgen und DTC-Zuständen.</li>\n<li>Schnittstellen und Nachrichten:</li>\n<li><code>Request: ClearDTCInformation(DTC)</code>: Diagnosenachricht vom Scan Tool an das Dcm.</li>\n<li><code>Dem_DcmClearDTC(Dem_ReturnClearDTCType, uint32, Dem_DTCFormatType, Dem_DTCOriginType)</code>: Synchroner C-API-Funktionsaufruf vom Dcm an das Dem zur Anforderung des Löschvorgangs.</li>\n<li><code>Positive or negative response()</code>: UDS-Antwortnachricht vom Dcm an das Scan Tool.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das <code>Generic Scan Tool</code> initiiert den Diagnoseablauf durch Senden der Nachricht <code>Request: ClearDTCInformation(DTC)</code> an das Modul <code>Dcm</code>.</li>\n<li>Das <code>Dcm</code> nimmt die Anfrage entgegen und ruft synchron die API-Funktion <code>Dem_DcmClearDTC(Dem_ReturnClearDTCType, uint32, Dem_DTCFormatType, Dem_DTCOriginType)</code> am Modul <code>Dem</code> auf.</li>\n<li>Das <code>Dem</code> verarbeitet die Anfrage und kehrt über die Rücksprungnachricht (gestrichelter Pfeil) zum <code>Dcm</code> zurück.</li>\n<li>Nach Abschluss des internen Vorgangs sendet das <code>Dcm</code> eine Diagnoseantwort (<code>Positive or negative response()</code>) zurück an das <code>Generic Scan Tool</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz veranschaulicht den synchronen Aufruf von <code>Dem_DcmClearDTC</code> durch das Dcm. Beachtenswert ist die Signaturangabe im Diagramm: Der erste Parameter ist formal als Rückgabetyp (<code>Dem_ReturnClearDTCType</code>) anstelle eines reinen Eingabeparameters notiert. Implementierer müssen die korrekte Parameterübergabe gemäß SWS-API-Spezifikation berücksichtigen (DTC-Wert als <code>uint32</code>, DTC-Format als <code>Dem_DTCFormatType</code>, Speicherursprung als <code>Dem_DTCOriginType</code>), während das Dem das Ergebnis zurückliefert, auf dessen Basis das Dcm eine positive oder negative UDS-Response generiert.</p>"}, {"id": "FIG-e4d57b0152e5010f", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion zwischen externem Diagnose-Tester (Generic Scan Tool), dem Diagnostic Communication Manager (Dcm) und dem Diagnostic Event Manager (Dem) im Rahmen des UDS-Dienstes zum Löschen von Fehlergedächtniseinträgen (Clear Diagnostic Information, Service 0x14 bzw. 0x04) innerhalb der AUTOSAR-Basissoftware.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>Generic Scan Tool</code>: Externes Diagnoseprüfgerät bzw. Tester.</li>\n<li><code>Dcm</code> («module»): Diagnostic Communication Manager der AUTOSAR-Basissoftware zur Protokollabwicklung der Diagnoseschicht.</li>\n<li><code>Dem</code> («module»): Diagnostic Event Manager der AUTOSAR-Basissoftware zur Verwaltung von Fehlerspeichereinträgen und DTC-Zuständen.</li>\n<li>Schnittstellen und Nachrichten:</li>\n<li><code>Request: ClearDTCInformation(DTC)</code>: Diagnosenachricht vom Scan Tool an das Dcm.</li>\n<li><code>Dem_DcmClearDTC(Dem_ReturnClearDTCType, uint32, Dem_DTCFormatType, Dem_DTCOriginType)</code>: Synchroner C-API-Funktionsaufruf vom Dcm an das Dem zur Anforderung des Löschvorgangs.</li>\n<li><code>Positive or negative response()</code>: UDS-Antwortnachricht vom Dcm an das Scan Tool.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Das <code>Generic Scan Tool</code> initiiert den Diagnoseablauf durch Senden der Nachricht <code>Request: ClearDTCInformation(DTC)</code> an das Modul <code>Dcm</code>.</li>\n<li>Das <code>Dcm</code> nimmt die Anfrage entgegen und ruft synchron die API-Funktion <code>Dem_DcmClearDTC(Dem_ReturnClearDTCType, uint32, Dem_DTCFormatType, Dem_DTCOriginType)</code> am Modul <code>Dem</code> auf.</li>\n<li>Das <code>Dem</code> verarbeitet die Anfrage und kehrt über die Rücksprungnachricht (gestrichelter Pfeil) zum <code>Dcm</code> zurück.</li>\n<li>Nach Abschluss des internen Vorgangs sendet das <code>Dcm</code> eine Diagnoseantwort (<code>Positive or negative response()</code>) zurück an das <code>Generic Scan Tool</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Sequenz veranschaulicht den synchronen Aufruf von <code>Dem_DcmClearDTC</code> durch das Dcm. Beachtenswert ist die Signaturangabe im Diagramm: Der erste Parameter ist formal als Rückgabetyp (<code>Dem_ReturnClearDTCType</code>) anstelle eines reinen Eingabeparameters notiert. Implementierer müssen die korrekte Parameterübergabe gemäß SWS-API-Spezifikation berücksichtigen (DTC-Wert als <code>uint32</code>, DTC-Format als <code>Dem_DTCFormatType</code>, Speicherursprung als <code>Dem_DTCOriginType</code>), während das Dem das Ergebnis zurückliefert, auf dessen Basis das Dcm eine positive oder negative UDS-Response generiert.</p>"}], "trans": [{"from": "FIG-c1c8ab414c6ba407", "to": "FIG-e4d57b0152e5010f", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Diagrammtitel: Die Überschrift „9.2 Dem_DcmClearDTC“ oberhalb der Lebenslinien wurde entfernt.</li>\n</ul>"}]};
